// Извлекаем текст из текстового/медиа-сообщения WhatsApp
const data = $input.first().json.body.data;
const msgType = data.messageType;
const msg = data.message || {};

let userMessage = '';
let mediaHint = '';

switch (msgType) {
  case 'conversation':
    userMessage = msg.conversation || '';
    break;
  case 'extendedTextMessage':
    userMessage = msg.extendedTextMessage?.text || '';
    break;
  case 'imageMessage':
    userMessage = msg.imageMessage?.caption || '[Пользователь прислал изображение без подписи]';
    mediaHint = '(изображение)';
    break;
  case 'videoMessage':
    userMessage = msg.videoMessage?.caption || '[Пользователь прислал видео]';
    mediaHint = '(видео)';
    break;
  case 'documentMessage':
    const fname = msg.documentMessage?.fileName || 'файл';
    userMessage = msg.documentMessage?.caption || `[Прислал документ: ${fname}]`;
    mediaHint = '(документ)';
    break;
  case 'stickerMessage':
    userMessage = '[Прислал стикер 😊 — ответь на него уместно]';
    break;
  case 'reactionMessage':
    userMessage = `[Поставил реакцию ${msg.reactionMessage?.text || '👍'} на сообщение]`;
    break;
  default:
    userMessage = `[Неизвестный тип: ${msgType}]`;
}

const sender = data.key?.participant || data.key?.remoteJid || 'unknown';
const chatId = data.key?.remoteJid || 'unknown';
const senderName = data.pushName || sender.replace('@s.whatsapp.net', '');

return [{
  json: {
    userMessage,
    mediaHint,
    sender,
    senderName,
    chatId,
    instanceName: $input.first().json.body.instance,
    messageType: msgType,
    isVoice: false
  }
}];

// Конвертируем base64 аудио в бинарный файл для Whisper
// Для работы: в Evolution Manager → Instance → Webhook → включи base64=true
const item = $input.first().json;
const data = item.body.data;

const base64Data = data.message?.base64
  || data.message?.audioMessage?.base64
  || data.message?.audioMessage?.jpegThumbnail; // fallback

if (!base64Data) {
  throw new Error('❌ base64 аудио не найдено! Открой Evolution Manager → Instance → Webhook → включи "Base64" для медиафайлов');
}

const sender = data.key?.participant || data.key?.remoteJid || 'unknown';
const chatId = data.key?.remoteJid || 'unknown';
const senderName = data.pushName || sender.replace('@s.whatsapp.net', '');

return [{
  json: {
    sender,
    senderName,
    chatId,
    instanceName: item.body.instance,
    messageType: 'audioMessage',
    isVoice: true
  },
  binary: {
    audioFile: {
      data: base64Data,
      mimeType: 'audio/ogg',
      fileName: 'voice.ogg'
    }
  }
}];

// Собираем данные после Whisper — берём транскрипт и мета из Декодировать аудио
const whisperResult = $input.first().json;
const transcript = whisperResult.text || '[Не удалось распознать речь]';

const prev = $('Декодировать аудио').first().json;

return [{
  json: {
    userMessage: `🎤 [голосовое]: ${transcript}`,
    mediaHint: '(голосовое сообщение)',
    sender: prev.sender,
    senderName: prev.senderName,
    chatId: prev.chatId,
    instanceName: prev.instanceName,
    messageType: 'audioMessage',
    isVoice: true
  }
}];

// Очищаем тег [VOICE] и убираем WA markdown для чистого TTS текста
const raw = $input.first().json.output;
const cleanText = raw.replace(/^\[VOICE\]\s*/, '').trim();

const ttsText = cleanText
  .replace(/\*([^*]+)\*/g, '$1')
  .replace(/_([^_]+)_/g, '$1')
  .replace(/~([^~]+)~/g, '$1')
  .replace(/`([^`]+)`/g, '$1')
  .trim();

const chatId = $('Evolution Webhook').first().json.body.data.key.remoteJid;
const instanceName = $('Evolution Webhook').first().json.body.instance;

return [{
  json: {
    cleanText,
    ttsText,
    chatId,
    instanceName,
    ttsBody: JSON.stringify({
      input: { text: ttsText },
      voice: {
        languageCode: 'ru-RU',
        name: 'ru-RU-Wavenet-D',
        ssmlGender: 'MALE'
      },
      audioConfig: {
        audioEncoding: 'MP3',
        speakingRate: 1.05
      }
    })
  }
}];
